INSERT INTO condiment_info VALUES(1,'食盐','氯化钠(NaCl)','咸味','钠离子、氯离子','1茶匙(5g)',0.0,2300.0,NULL,NULL,NULL,NULL,'调味、防腐、促进蛋白质变性','NaCl解离产生Na+和Cl-，刺激味蕾咸味受体','维持电解质平衡、促进消化','过量导致高血压、心血管疾病','不超过5g/天','2026-06-04 12:02:17',NULL,'食品化学教材 / 中国营养学会','食品化学教材 + 中国营养学会','https://books.google.com/ | https://www.cnsoc.org/','curated/compiled');
INSERT INTO condiment_info VALUES(2,'白糖','蔗糖(C12H22O11)','甜味','葡萄糖、果糖','1茶匙(4g)',16.0,0.0,NULL,NULL,NULL,NULL,'增甜、上色、发酵底物','蔗糖水解为葡萄糖和果糖，刺激甜味受体','快速补充能量','过量导致肥胖、糖尿病、龋齿','不超过25g/天','2026-06-04 12:02:17',NULL,'食品化学教材 / 中国营养学会','食品化学教材 + 中国营养学会','https://books.google.com/ | https://www.cnsoc.org/','curated/compiled');
INSERT INTO condiment_info VALUES(3,'生抽','氨基酸、食盐、糖','鲜味、咸味','谷氨酸、天冬氨酸','1汤匙(15ml)',8.0,900.0,NULL,NULL,NULL,NULL,'调味、增鲜、上色','氨基酸提供鲜味(谷氨酸)，美拉德反应增色','提供氨基酸','含钠量高','控制用量','2026-06-04 12:02:17',NULL,'食品化学教材 / 中国营养学会','食品化学教材 + 中国营养学会','https://books.google.com/ | https://www.cnsoc.org/','curated/compiled');
INSERT INTO condiment_info VALUES(4,'醋','乙酸(CH3COOH)','酸味','醋酸、氨基酸','1汤匙(15ml)',3.0,0.0,NULL,NULL,NULL,NULL,'去腥、软化肉质、防腐','醋酸使蛋白质变性，软化纤维','促进钙吸收、降低GI','过量刺激胃','适量使用','2026-06-04 12:02:17',NULL,'食品化学教材 / 中国营养学会','食品化学教材 + 中国营养学会','https://books.google.com/ | https://www.cnsoc.org/','curated/compiled');
