INSERT INTO chemical_reactions VALUES(1,'美拉德反应','Maillard Reaction','褐变',140.0,165.0,NULL,NULL,NULL,NULL,'氨基酸与还原糖在加热条件下发生缩合反应，生成席夫碱，经Amadori重排、脱水、裂解等步骤生成褐色物质和香味物质','氨基酸 + 还原糖',NULL,'类黑精、呋喃、吡嗪、噻吩等','白色→黄色→褐色','产生烤香、焦香、坚果香',NULL,NULL,'抗氧化物质(类黑精)','丙烯酰胺(淀粉类食物>120°C)','高温产生致癌物，但正常烹饪有益','高温、碱性环境、低水分活度','酸性环境、低温、高水分活度','烤肉、烘焙、炒菜、咖啡','煎牛排、烤面包、炒洋葱、咖啡烘焙','2026-06-04 12:02:17',NULL,'食品化学教材','食品化学教材','https://books.google.com/','manual/curated');
INSERT INTO chemical_reactions VALUES(2,'焦糖化反应','Caramelization','褐变',170.0,210.0,NULL,NULL,NULL,NULL,'糖在高温下发生脱水、聚合反应，生成焦糖色素和焦糖风味物质','蔗糖、葡萄糖、果糖',NULL,'焦糖色素、二乙酰、呋喃类','白色→浅黄→深褐色','产生焦糖香、苦甜味',NULL,NULL,'焦糖色素(天然色素)','过量羟甲基糠醛(HMF)','适量无害，过量可能有害','高温、少量酸','低温、大量水','炒糖色、烘焙、糖果','红烧肉糖色、焦糖布丁、可乐','2026-06-04 12:02:17',NULL,'食品化学教材','食品化学教材','https://books.google.com/','manual/curated');
INSERT INTO chemical_reactions VALUES(3,'蛋白质变性','Protein Denaturation','变性',40.0,100.0,NULL,NULL,NULL,NULL,'加热使蛋白质空间结构破坏，氢键断裂，蛋白质展开并重新聚集','天然蛋白质',NULL,'变性蛋白质','透明→不透明','质地变化(凝固)',NULL,NULL,'更易消化吸收','过度变性导致口感变老','提高蛋白质消化率','中等温度、适当时间','极高温、长时间','煮蛋、蒸蛋、炖肉','鸡蛋凝固、肉煮熟','2026-06-04 12:02:17',NULL,'食品化学教材','食品化学教材','https://books.google.com/','manual/curated');
INSERT INTO chemical_reactions VALUES(4,'淀粉糊化','Starch Gelatinization','糊化',55.0,85.0,NULL,NULL,NULL,NULL,'淀粉颗粒吸水膨胀，结晶区破坏，淀粉分子溶出形成粘稠糊状','淀粉颗粒 + 水',NULL,'淀粉糊','白色不透明→半透明','质地变粘稠',NULL,NULL,'更易消化','高GI值','快速升高血糖','加热、加水','低温、低水分','煮饭、勾芡、烘焙','米饭变软、勾芡变稠','2026-06-04 12:02:17',NULL,'食品化学教材','食品化学教材','https://books.google.com/','manual/curated');
INSERT INTO chemical_reactions VALUES(5,'脂肪氧化','Lipid Oxidation','氧化',0.0,200.0,NULL,NULL,NULL,NULL,'不饱和脂肪酸双键被氧气攻击，生成过氧化物，分解产生醛、酮等','不饱和脂肪酸 + 氧气',NULL,'过氧化物、醛、酮','无明显变化','产生哈喇味、异味',NULL,NULL,'无','自由基、过氧化物','促进衰老、炎症','高温、光照、金属离子','低温、避光、抗氧化剂','油炸、储存不当','油脂变质、油炸过度','2026-06-04 12:02:17',NULL,'食品化学教材','食品化学教材','https://books.google.com/','manual/curated');
INSERT INTO chemical_reactions VALUES(6,'维生素C氧化','Vitamin C Oxidation','氧化',0.0,100.0,NULL,NULL,NULL,NULL,'抗坏血酸被氧化为脱氢抗坏血酸，进一步氧化为二酮古洛糖酸','抗坏血酸(维生素C)',NULL,'脱氢抗坏血酸、二酮古洛糖酸','无明显变化','营养流失',NULL,NULL,'无','无(但维生素C失活)','营养损失','高温、碱性、氧气、金属离子','酸性、低温、隔氧','蔬菜烹饪、果汁放置','蔬菜炒久变黄','2026-06-04 12:02:17',NULL,'食品化学教材','食品化学教材','https://books.google.com/','manual/curated');
INSERT INTO chemical_reactions VALUES(7,'胶原蛋白水解','Collagen Hydrolysis','水解',70.0,100.0,NULL,NULL,NULL,NULL,'胶原蛋白三螺旋结构在热水中逐渐解离，水解为明胶','胶原蛋白',NULL,'明胶、氨基酸','不透明→透明','肉质变软烂',NULL,NULL,'明胶更易吸收','无','改善口感，易消化','低温长时间、酸性环境','高温短时间','炖肉、熬汤','炖肉变软、骨头汤变浓','2026-06-04 12:02:17',NULL,'食品化学教材','食品化学教材','https://books.google.com/','manual/curated');
INSERT INTO chemical_reactions VALUES(8,'酯化反应','Esterification','酯化',0.0,100.0,NULL,NULL,NULL,NULL,'有机酸与醇在酸性条件下反应生成酯，产生水果香味','有机酸 + 醇',NULL,'酯类(香味物质)','无明显变化','产生果香、花香',NULL,NULL,'香味物质','无','增香','酸性环境、适当温度','碱性环境','酿酒、腌制','酒香、果香','2026-06-04 12:02:17',NULL,'食品化学教材','食品化学教材','https://books.google.com/','manual/curated');
